algorithms.pseudocode:
PREPROCESS(h, l):                        // once per key
  order <- indices of l sorted by h(l[i])
  arr   <- l permuted by order
  keys  <- [ h(y) for y in arr ]         // monotone non-decreasing
  return arr, keys

BSEARCH(keys, t, lo, len):               // returns (index or NONE, cost)
  if len = 0: return (NONE, 0)
  half <- floor(len/2) ; m <- lo + half
  if keys[m] = t:   return (m, 1)
  if keys[m] < t:   (i,c) <- BSEARCH(keys, t, m+1, len-half-1)
  else:             (i,c) <- BSEARCH(keys, t, lo,  half)
  return (i, c+1)                        // cost <= floor(log2 len) + 1

DECODE(arr, keys, t):
  (m, cost) <- BSEARCH(keys, t, 0, n)
  if m = NONE: return (ABSTAIN, cost)
  if m > 0:    cost <- cost+1 ; if keys[m-1] = t: return (ABSTAIN, cost)
  if m+1 < n:  cost <- cost+1 ; if keys[m+1] = t: return (ABSTAIN, cost)
  return (arr[m], cost)                  // cost <= floor(log2 n) + 3
